-- ============================================================
-- 005b_seed_levels.sql
-- Seed de institution_levels desde el CSV definitivo.
--
-- Fuente:
--   escuelas_cordoba - seed (2)(1).csv
--
-- SOLO carga institution_levels.
-- Requiere que 005a_seed_institutions.sql haya sido ejecutado.
-- ============================================================

BEGIN;

-- ------------------------------------------------------------
-- Preflight de seguridad
-- ------------------------------------------------------------

DO $$
DECLARE
    institution_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO institution_count
    FROM institutions;

    IF institution_count <> 5489 THEN
        RAISE EXCEPTION
            'Seed cancelado: institutions contiene % registros; se esperaban 5489.',
            institution_count;
    END IF;

    IF EXISTS (SELECT 1 FROM institution_levels) THEN
        RAISE EXCEPTION
            'Seed cancelado: institution_levels ya contiene datos.';
    END IF;
END $$;

-- ------------------------------------------------------------
-- Carga
--
-- El CSV utiliza:
--   Común - Primario
--   Común - Inicial
--   Común - Secundario
--   Jóvenes y Adultos - Secundario
--
-- Se normaliza como:
--   modalidad = Común / Jóvenes y Adultos
--   level     = Primario / Inicial / Secundario
--
-- Para:
--   Especial
--   Formación Profesional
--   Artística
--   Hospitalaria
--
-- no se inventa modalidad: queda NULL.
--
-- empresa queda NULL porque el CSV definitivo no contiene
-- ese dato.
-- ------------------------------------------------------------

INSERT INTO institution_levels (
    id,
    institution_id,
    level,
    modalidad,
    empresa
)
SELECT
    gen_random_uuid()::text,
    i.id,
    source.level,
    source.modalidad,
    NULL
