JOIN institutions i
    ON i.cue = source.cue;

-- ------------------------------------------------------------
-- Validación
-- ------------------------------------------------------------

DO $$
DECLARE
    total INTEGER;
    con_institucion INTEGER;
    duplicados INTEGER;
BEGIN
    SELECT COUNT(*) INTO total
    FROM institution_levels;

    SELECT COUNT(*) INTO con_institucion
    FROM institution_levels il
    JOIN institutions i
      ON i.id = il.institution_id;

    SELECT COUNT(*) INTO duplicados
    FROM (
        SELECT
            institution_id,
            level,
            COALESCE(modalidad, '') AS modalidad_normalizada,
            COUNT(*) AS cantidad
        FROM institution_levels
        GROUP BY
            institution_id,
            level,
            COALESCE(modalidad, '')
        HAVING COUNT(*) > 1
    ) d;

    IF total <> 6260 THEN
        RAISE EXCEPTION
            'Cantidad inesperada de institution_levels: % (esperado 6260)',
            total;
    END IF;

    IF con_institucion <> total THEN
        RAISE EXCEPTION
            'Hay institution_levels sin institución válida: %',
            total - con_institucion;
    END IF;

    IF duplicados <> 0 THEN
        RAISE EXCEPTION
            'Se encontraron % combinaciones duplicadas de institución + nivel + modalidad',
            duplicados;
    END IF;
END $$;

COMMIT;
